use eframe::egui::{self,Color32,RichText};
use serde::{Deserialize,Serialize};use serde_json::{json,Value};use anyhow::{ensure,Result};
use std::{collections::{BTreeMap,HashSet},sync::{Arc,RwLock,mpsc},time::{Duration,Instant}};
use crate::{domain::{self,Bank,Question},store::{Store,Revision,id,now,asset_refs,sha},network::Config,platform::Bridge,materials,ai,harness,sync};
use base64::{Engine,engine::general_purpose::STANDARD};
#[derive(Clone,Default,Serialize,Deserialize)]struct Answer{#[serde(default)]text:String,#[serde(default)]selected:Vec<String>,#[serde(default)]verdict:Option<bool>,#[serde(default)]image:String}
#[derive(Clone,Serialize,Deserialize)]struct Session{id:String,questions:Vec<Question>,answers:BTreeMap<String,Answer>,index:usize,exam:bool,deadline:u64,submitted:bool}
enum Output{Info(String),Bank(Bank),Material(Value),Grade(Value),Export(Value,String),Synced(String)}
pub struct EasyGot{
    store:Store,bridge:Bridge,config:Config,shared:harness::SharedConfig,
    tab:usize,view:String,status:String,busy:bool,rx:mpsc::Receiver<Result<Output,String>>,tx:mpsc::Sender<Result<Output,String>>,
    filter:String,selected:HashSet<String>,role:usize,strict:String,material:Option<Revision>,
    session:Option<Session>,session_base:Option<String>,result:Option<Value>,image_for:String,
    editor:String,draft_kind:String,edit_id:String,edit_base:Option<String>,confirm:String,
    query:String,spec:String,minutes:u32,wrong:bool,
}
impl EasyGot{
    pub fn new(cc:&eframe::CreationContext<'_>,app:android_activity::AndroidApp)->Self{
        let mut fonts=egui::FontDefinitions::default();for path in ["/system/fonts/NotoSansCJK-Regular.ttc","/system/fonts/NotoSansSC-Regular.otf","/system/fonts/DroidSansFallback.ttf"]{if let Ok(bytes)=std::fs::read(path){fonts.font_data.insert("cjk".into(),egui::FontData::from_owned(bytes).into());fonts.families.entry(egui::FontFamily::Proportional).or_default().insert(0,"cjk".into());fonts.families.entry(egui::FontFamily::Monospace).or_default().push("cjk".into());break;}}cc.egui_ctx.set_fonts(fonts);cc.egui_ctx.set_visuals(egui::Visuals::light());
        let mut style=(*cc.egui_ctx.style()).clone();style.spacing.item_spacing=egui::vec2(10.,10.);style.spacing.button_padding=egui::vec2(12.,10.);style.text_styles.insert(egui::TextStyle::Body,egui::FontId::proportional(17.));cc.egui_ctx.set_style(style);
        let bridge=Bridge{app:app.clone()};let root=app.internal_data_path().expect("Android files directory");let store=Store::open(&root).expect("open local database");
        let config=bridge.call("loadConfig","").ok().and_then(|s|serde_json::from_str::<Config>(&s).ok()).unwrap_or_default();let shared=Arc::new(RwLock::new(config.clone()));let status=harness::start(store.clone(),shared.clone()).err().map(|e|e.to_string()).unwrap_or_default();
        let(tx,rx)=mpsc::channel();Self{store,bridge,config,shared,tab:0,view:String::new(),status,busy:false,rx,tx,filter:String::new(),selected:HashSet::new(),role:0,strict:String::new(),material:None,session:None,session_base:None,result:None,image_for:String::new(),editor:String::new(),draft_kind:String::new(),edit_id:String::new(),edit_base:None,confirm:String::new(),query:String::new(),spec:serde_json::to_string_pretty(&json!({"title":"专项练习","chapter":"","knowledgePoints":"","count":5,"difficulty":3,"typeCounts":{"single":2,"multiple":1,"boolean":1,"short":1},"weights":{}})).unwrap(),minutes:30,wrong:true}
    }
    fn job(&mut self,title:&str,work:impl FnOnce()->Result<Output>+Send+'static){if self.busy{self.status="正在处理上一项任务，请稍候".into();return;}self.busy=true;self.status=title.into();let tx=self.tx.clone();std::thread::spawn(move||{let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(work)).map_err(|_|"任务意外终止，原数据保留".to_owned()).and_then(|r|r.map_err(|e|e.to_string()));let _=tx.send(result);});}
    fn info(&mut self,result:Result<()>){match result{Ok(())=>self.status="已保存".into(),Err(e)=>self.status=e.to_string()}}
    fn list(&self,kind:&str)->Vec<Revision>{self.store.list(kind).unwrap_or_default()}
    fn go(&mut self,tab:usize){let _=self.save_session();self.tab=tab;self.view.clear();self.filter.clear();}
    fn heading(ui:&mut egui::Ui,title:&str){ui.add_space(8.);ui.label(RichText::new(title).size(22.).strong().color(Color32::from_rgb(22,116,91)));ui.add_space(6.);}
    fn edit(ui:&mut egui::Ui,label:&str,value:&mut String,password:bool){ui.label(label);ui.add(egui::TextEdit::singleline(value).password(password).desired_width(f32::INFINITY));}
    fn multiline(ui:&mut egui::Ui,text:&mut String,rows:usize){ui.add(egui::TextEdit::multiline(text).desired_width(f32::INFINITY).desired_rows(rows));}
    fn bank_import(&mut self,mut bank:Bank)->Result<()>{bank.validate()?;for(hash,value)in &bank.assets{let bytes=STANDARD.decode(value)?;ensure!(sha(&bytes)==*hash,"素材校验失败");self.store.asset(&bytes)?;}let refs=asset_refs(&serde_json::to_value(&bank.questions)?);for hash in refs{ensure!(self.store.asset_path(&hash)?.exists(),"题目缺少图片素材");}
        for q in &mut bank.questions{self.store.save("question",&q.id,serde_json::to_value(q.clone())?,None,false,false)?;}Ok(())}
    fn new_session(&mut self,questions:Vec<Question>,exam:bool)->Result<()>{ensure!(!questions.is_empty(),"没有可练习题目");let session=Session{id:id(),questions,answers:BTreeMap::new(),index:0,exam,deadline:if exam{now()+self.minutes as u64*60000}else{0},submitted:false};self.session=Some(session);self.session_base=None;self.save_session()?;self.view="question".into();Ok(())}
    fn save_session(&mut self)->Result<()>{if let Some(s)=&self.session{let rev=self.store.save("session",&s.id,serde_json::to_value(s)?,self.session_base.as_deref(),false,false)?;self.session_base=Some(rev.version);}Ok(())}
    fn attempt(&self,s:&Session,q:&Question)->Result<Value>{let a=s.answers.get(&q.id).cloned().unwrap_or_default();let value=if q.kind=="boolean"{json!(a.verdict)}else{json!(a.selected)};let payload=json!({"id":format!("{}:{}",s.id,q.id),"sessionId":s.id,"questionId":q.id,"question":q,"answer":a,"title":domain::clip(&q.stem,100),"maxScore":q.max_score,"score":if q.subjective(){0.}else{q.score(&value)?},"pending":q.subjective(),"answeredAt":now(),"explanation":q.explanation,"feedback":"按标准答案判定"});self.store.save("attempt",payload["id"].as_str().unwrap(),payload.clone(),None,false,false)?;Ok(payload)}
    fn finish_exam(&mut self)->Result<()>{if let Some(s)=&self.session{if s.submitted{return Ok(());}for q in &s.questions{self.attempt(s,q)?;}}if let Some(s)=self.session.as_mut(){s.submitted=true;}self.save_session()?;self.view="summary".into();Ok(())}
    fn poll(&mut self){
        while let Ok(result)=self.rx.try_recv(){self.busy=false;match result{Err(error)=>self.status=error,Ok(Output::Info(s))=>self.status=s,Ok(Output::Synced(s))=>{self.status=s;self.session=None;self.session_base=None;},Ok(Output::Bank(bank))=>{self.editor=serde_json::to_string_pretty(&bank).unwrap_or_default();self.draft_kind="bank".into();self.view="editor".into();self.status="请核对题目、答案和来源，再确认入库".into();},Ok(Output::Material(material))=>{self.material=self.store.get(material["id"].as_str().unwrap_or("")).ok().flatten();self.view="material".into();self.status="资料已保存，可离线阅读检索".into();},Ok(Output::Grade(value))=>{self.result=Some(value);self.view="result".into();self.status="评分已保存，请结合参考答案核对".into();},Ok(Output::Export(value,name))=>{let result=(||->Result<()>{let path=self.store.root.join("export.json");std::fs::write(&path,serde_json::to_vec_pretty(&value)?)?;self.bridge.call("export",&json!({"path":path,"name":name}).to_string())?;Ok(())})();self.info(result);}}}
        if let Ok(event)=self.bridge.call("poll",""){if !event.is_empty(){if let Ok(v)=serde_json::from_str::<Value>(&event){self.import_event(v);}else{self.status=event;}}}
    }
    fn import_event(&mut self,event:Value){let kind=event["kind"].as_u64().unwrap_or(0);if kind==20{self.status="文件已导出".into();return;}let path=event["path"].as_str().unwrap_or("").to_owned();let name=event["name"].as_str().unwrap_or("资料").to_owned();let store=self.store.clone();
        if kind==1{self.job("读取JSON题库…",move||{let data=std::fs::read(path)?;let bank:Bank=serde_json::from_slice(&data)?;bank.validate()?;Ok(Output::Bank(bank))});}
        else if kind==2{let role=["textbook","syllabus","past_paper"][self.role].to_owned();let strict=self.strict.clone();self.job("提取教材原文…",move||{let data=std::fs::read(path)?;let material=materials::import(&store,&name,&data,&role,&strict)?;Ok(Output::Material(material))});}
        else if kind==3{let result=(||->Result<()>{let bytes=std::fs::read(path)?;image::guess_format(&bytes)?;let hash=store.asset(&bytes)?;if let Some(s)=self.session.as_mut(){s.answers.entry(self.image_for.clone()).or_default().image=hash;}self.save_session()?;Ok(())})();self.info(result);}
        else if kind==4{self.job("合并完整备份…",move||{let value:Value=serde_json::from_slice(&std::fs::read(path)?)?;ensure!(value["backupVersion"]==1,"备份版本不兼容");import_assets(&store,&value)?;let revisions:Vec<Revision>=serde_json::from_value(value["revisions"].clone())?;for hash in asset_refs(&value["revisions"]){ensure!(store.asset_path(&hash)?.exists(),"备份缺少素材");}store.ingest(&revisions)?;Ok(Output::Synced("备份已合并，请检查同步冲突".into()))});}
    }
    fn home(&mut self,ui:&mut egui::Ui){Self::heading(ui,"今天，也学懂一点");let questions=self.list("question");let attempts=self.list("attempt");let wrong=self.store.wrong().unwrap_or_default();ui.label(format!("{} 道题  ·  {} 道最近失分题  ·  {} 份资料",questions.len(),wrong.len(),self.list("material").len()));
        if ui.button("开始章节 / 知识点练习").clicked(){self.go(1);}if ui.button("复习错题").clicked(){let qs=wrong.iter().filter_map(|a|serde_json::from_value::<Question>(a["question"].clone()).ok()).collect();let r=self.new_session(qs,false);self.info(r);}
        if questions.is_empty()&&ui.button("载入示例题库").clicked(){let r=serde_json::from_str::<Bank>(include_str!("../../examples/sample-bank.json")).map_err(anyhow::Error::from).and_then(|b|self.bank_import(b));self.info(r);}
        Self::heading(ui,"继续学习");for r in self.list("session"){if r.payload["submitted"]==true{continue;}if ui.button(format!("继续{} · {}题",if r.payload["exam"]==true{"模拟考试"}else{"逐题练习"},r.payload["questions"].as_array().map_or(0,|a|a.len()))).clicked(){match serde_json::from_value::<Session>(r.payload){Ok(s)=>{self.session=Some(s);self.session_base=Some(r.version);self.view="question".into();},Err(e)=>self.status=e.to_string()}}}
        Self::heading(ui,"最近作答 / 待评分");for r in attempts.into_iter().take(20){let a=r.payload;let title=if a["pending"]==true{format!("{} · 待AI评分",a["title"].as_str().unwrap_or(""))}else{format!("{} · {} / {}",a["title"].as_str().unwrap_or(""),a["score"],a["maxScore"])};if ui.button(title).clicked(){self.result=Some(a);self.view="result".into();}}
    }
    fn bank_ui(&mut self,ui:&mut egui::Ui){Self::heading(ui,"我的题库");if ui.button("导入JSON标准题库").clicked(){let r=self.bridge.call("pick","1").map(|_|());self.info(r);}if ui.button("导出题库JSON").clicked(){let store=self.store.clone();self.job("准备导出…",move||{let qs=store.list("question")?.into_iter().map(|r|r.payload).collect::<Vec<_>>();let mut value=json!({"schemaVersion":1,"title":"EasyGot题库","questions":qs});add_assets(&store,&mut value)?;Ok(Output::Export(value,"EasyGot-bank.json".into()))});}
        if ui.button("新增题目").clicked(){self.editor=json!({"id":id(),"type":"short","stem":"填写题干","maxScore":5,"referenceAnswer":"填写参考答案","origin":"original","sources":[],"materialIds":[],"knowledgePoints":[]}).to_string();self.draft_kind="question".into();self.edit_base=None;self.edit_id.clear();self.view="editor".into();}
        Self::edit(ui,"搜索章节、知识点、题干",&mut self.filter,false);let qs:Vec<Question>=self.list("question").into_iter().filter_map(|r|serde_json::from_value::<Question>(r.payload).ok()).filter(|q|format!("{} {} {}",q.stem,q.chapter,q.knowledge_points.join(" ")).contains(&self.filter)).collect();ui.label(format!("当前筛选 {} 题",qs.len()));
        ui.horizontal_wrapped(|ui|{if ui.button("逐题练习").clicked(){let r=self.new_session(qs.clone(),false);self.info(r);}ui.add(egui::DragValue::new(&mut self.minutes).range(1..=360).suffix(" 分钟"));if ui.button("计时模拟考试").clicked(){let r=self.new_session(qs.clone(),true);self.info(r);}});
        for q in qs.into_iter().take(100){egui::Frame::group(ui.style()).show(ui,|ui|{ui.label(format!("{} · {}",domain::label(&q.kind),q.chapter));ui.label(&q.stem);if ui.button("编辑题目").clicked(){self.editor=serde_json::to_string_pretty(&q).unwrap_or_default();self.draft_kind="question".into();self.edit_id=q.id.clone();self.edit_base=self.store.get(&q.id).ok().flatten().map(|r|r.version);self.view="editor".into();}});}
    }
    fn question_ui(&mut self,ui:&mut egui::Ui){let Some(mut session)=self.session.clone()else{self.view.clear();return;};if session.submitted{self.view="summary".into();return;}if session.exam{let left=session.deadline.saturating_sub(now());ui.colored_label(Color32::from_rgb(22,116,91),format!("剩余 {}分{}秒",left/60000,left/1000%60));if left==0{let r=self.finish_exam();self.info(r);return;}}
        let q=session.questions[session.index].clone();Self::heading(ui,&format!("{} / {} · {} · {}分",session.index+1,session.questions.len(),domain::label(&q.kind),q.max_score));ui.label(RichText::new(&q.stem).size(20.));if !q.image.is_empty(){self.picture(ui,&q.image);}let answer=session.answers.entry(q.id.clone()).or_default();let mut changed=false;
        match q.kind.as_str(){"single"=>for option in &q.options{if ui.radio(answer.selected==vec![option.id.clone()],format!("{}. {}",option.id,option.text)).clicked(){answer.selected=vec![option.id.clone()];changed=true;}},"multiple"=>for option in &q.options{let mut on=answer.selected.contains(&option.id);if ui.checkbox(&mut on,format!("{}. {}",option.id,option.text)).changed(){answer.selected.retain(|x|x!=&option.id);if on{answer.selected.push(option.id.clone());}changed=true;}},"boolean"=>{changed|=ui.radio_value(&mut answer.verdict,Some(true),"正确").changed();changed|=ui.radio_value(&mut answer.verdict,Some(false),"错误").changed();},_=>{changed|=ui.add(egui::TextEdit::multiline(&mut answer.text).desired_width(f32::INFINITY).desired_rows(6).hint_text("输入答案，或上传手写照片")).changed();if ui.button("选择手写答案图片").clicked(){self.image_for=q.id.clone();let r=self.bridge.call("pick","3").map(|_|());self.info(r);}if !answer.image.is_empty(){self.picture(ui,&answer.image);if ui.button("移除作答图片").clicked(){answer.image.clear();changed=true;}}}}
        let mut submit=false;ui.horizontal_wrapped(|ui|{if session.index>0&&ui.button("上一题").clicked(){session.index-=1;changed=true;}if session.index+1<session.questions.len()&&ui.button("下一题").clicked(){session.index+=1;changed=true;}if !session.exam&&ui.button("提交本题").clicked(){submit=true;}if session.exam&&ui.button("交卷").clicked(){self.confirm="exam".into();}});
        if ui.button("本题笔记").clicked(){let key=format!("note:{}",q.id);let old=self.store.get(&key).ok().flatten();self.editor=old.as_ref().map(|r|r.payload["text"].as_str().unwrap_or("").into()).unwrap_or_default();self.edit_base=old.map(|r|r.version);self.edit_id=key;self.draft_kind="note".into();self.view="editor".into();}
        self.session=Some(session.clone());if changed{let r=self.save_session();self.info(r);}if submit{match self.attempt(&session,&q){Ok(a)=>{self.result=Some(a);self.view="result".into();},Err(e)=>self.status=e.to_string()}}
    }
    fn picture(&self,ui:&mut egui::Ui,hash:&str){ui.small(format!("图片已保存：{}",domain::clip(hash,12)));if let Ok(path)=self.store.asset_path(hash){if let Ok(bytes)=std::fs::read(path){if let Ok(image)=image::load_from_memory(&bytes){let rgba=image.thumbnail(800,1000).into_rgba8();let texture=ui.ctx().load_texture(hash,egui::ColorImage::from_rgba_unmultiplied([rgba.width()as usize,rgba.height()as usize],&rgba),Default::default());let size=texture.size_vec2();let factor=(ui.available_width()/size.x).min(1.);ui.image((texture.id(),size*factor));}}}}
    fn result_ui(&mut self,ui:&mut egui::Ui){let Some(a)=self.result.clone()else{return;};Self::heading(ui,if a["pending"]==true{"作答已保存，等待AI评分"}else{"答题反馈"});ui.label(a["title"].as_str().unwrap_or(""));ui.label(format!("你的作答：{}",a["answer"]["text"].as_str().unwrap_or("")));if let Some(hash)=a["answer"]["image"].as_str().filter(|s|!s.is_empty()){self.picture(ui,hash);}if a["pending"]!=true{ui.heading(format!("{} / {} 分",a["score"],a["maxScore"]));ui.label(a["feedback"].as_str().unwrap_or(""));ui.label(a["explanation"].as_str().unwrap_or(""));if a["citations"].is_array(){ui.label(format!("教材引用：{}",a["citations"]));}}
        if ui.button("AI评分与详解（联网）").clicked(){let store=self.store.clone();let config=self.config.clone();let mut attempt=a.clone();self.job("对照参考答案和教材评分…",move||{let q:Question=serde_json::from_value(attempt["question"].clone())?;let grade=ai::grade(&store,&config,&q,&attempt["answer"])?;for(k,v)in grade.as_object().unwrap(){attempt[k]=v.clone();}attempt["pending"]=json!(false);store.save("attempt",attempt["id"].as_str().unwrap(),attempt.clone(),None,false,false)?;Ok(Output::Grade(attempt))});}
        ui.small("此操作发送本题、作答图片和相关教材片段到你配置的视觉模型。");ui.separator();ui.label(format!("参考答案：{}",if a["question"]["referenceAnswer"].as_str().is_some_and(|s|!s.is_empty()){a["question"]["referenceAnswer"].clone()}else{a["question"]["answer"].clone()}));ui.label(a["question"]["explanation"].as_str().unwrap_or(""));
        if ui.button("继续练习").clicked(){self.view=if self.session.as_ref().is_some_and(|s|s.submitted){"summary".into()}else{"question".into()};}
    }
    fn summary(&mut self,ui:&mut egui::Ui){Self::heading(ui,"本轮结果");let Some(s)=self.session.clone()else{return;};let mut score=0.;let mut max=0.;let mut pending=0;for r in self.list("attempt"){let a=r.payload;if a["sessionId"].as_str()!=Some(&s.id){continue;}max+=a["maxScore"].as_f64().unwrap_or(0.);if a["pending"]==true{pending+=1;}else{score+=a["score"].as_f64().unwrap_or(0.);}if ui.button(format!("{} · {}",a["title"].as_str().unwrap_or(""),if a["pending"]==true{"待评分".into()}else{a["score"].to_string()})).clicked(){self.result=Some(a);self.view="result".into();}}ui.heading(format!("已得 {score} / {max} 分"));ui.label(format!("还有 {pending} 题待AI评分"));}
    fn library(&mut self,ui:&mut egui::Ui){Self::heading(ui,"教材、考纲与往年试题");ui.horizontal_wrapped(|ui|{for(i,label)in ["教材","考纲","往年试题"].iter().enumerate(){ui.selectable_value(&mut self.role,i,*label);}});Self::edit(ui,"资料严格要求（可选）",&mut self.strict,false);if ui.button("导入PDF / Word DOCX / TXT / Markdown").clicked(){let r=self.bridge.call("pick","2").map(|_|());self.info(r);}Self::edit(ui,"搜索原文",&mut self.filter,false);
        if !self.filter.is_empty(){if let Ok(hits)=materials::search(&self.store,&self.filter,&self.selected){if let Some(arr)=hits.as_array(){for hit in arr{egui::Frame::group(ui.style()).show(ui,|ui|{ui.label(RichText::new(format!("{} · {}",hit["title"].as_str().unwrap_or(""),hit["locator"].as_str().unwrap_or(""))).strong());ui.label(hit["text"].as_str().unwrap_or(""));});}}}}
        for r in self.list("material"){let key=r.entity_id.clone();let m=&r.payload;egui::Frame::group(ui.style()).show(ui,|ui|{let mut selected=self.selected.contains(&key);if ui.checkbox(&mut selected,m["title"].as_str().unwrap_or("资料")).changed(){if selected{self.selected.insert(key.clone());}else{self.selected.remove(&key);}}ui.small(format!("{} · {}段/页",m["role"].as_str().unwrap_or(""),m["sections"].as_array().map_or(0,|v|v.len())));if ui.button("阅读 / 图片识别").clicked(){self.material=Some(r.clone());self.filter.clear();self.view="material".into();}});}
    }
    fn material_ui(&mut self,ui:&mut egui::Ui){let Some(r)=self.material.clone()else{return;};let m=r.payload;Self::heading(ui,m["title"].as_str().unwrap_or("教材"));ui.label(format!("严格要求：{}",m["strictRules"].as_str().unwrap_or("无")));Self::edit(ui,"本文件内查找",&mut self.filter,false);
        if ui.button("AI识别文档内图片 / PDF页面（联网）").clicked(){self.confirm="ocr".into();}
        if let Some(sections)=m["sections"].as_array(){for s in sections.iter().filter(|s|self.filter.is_empty()||s["text"].as_str().unwrap_or("").contains(&self.filter)).take(100){egui::Frame::group(ui.style()).show(ui,|ui|{ui.small(s["locator"].as_str().unwrap_or(""));ui.label(s["text"].as_str().filter(|s|!s.is_empty()).unwrap_or("本页没有可提取文字，可使用视觉识别。"));});}}
        if ui.button("修改严格要求").clicked(){self.editor=m["strictRules"].as_str().unwrap_or("").into();self.edit_id=r.entity_id;self.edit_base=Some(r.version);self.draft_kind="strict".into();self.view="editor".into();}
    }
    fn assistant(&mut self,ui:&mut egui::Ui){Self::heading(ui,"AI 学习工作台");ui.label("完整DeepSeek Harness基座 · 学习工具由Rust提供");ui.label("题目讲解 / 主观题批改 / 错题归因 / 教材查询 / 变式出题 / 复习计划");
        if ui.button("打开AI助教 / 首次安装运行环境").clicked(){let r=self.bridge.call("openHarness","").map(|_|());self.info(r);}ui.small("首次按上游流程下载proot Ubuntu、Node与Harness；评分模型配置与Harness模型配置分别管理。");
        if ui.button("安装 / 更新EasyGot学习工具到Harness").clicked(){let bridge=self.bridge.clone();let store=self.store.clone();let shared=self.shared.clone();self.job("安装学习工具（首次可能需要下载插件依赖）…",move||{harness::start(store,shared)?;let result=bridge.call("installHarnessTools","")?;let value:Value=serde_json::from_str(&result)?;ensure!(value["ok"]==true,"工具安装未完成：{}",value["output"]);Ok(Output::Info("学习工具已安装，请重启AI助教服务以刷新工具列表".into()))});}
        ui.small("学习工具包含教材搜索、错题读取、DeepSeek联网搜索/抓取、主观题评分、提交新题草稿和保存复习计划。");
        if ui.button("按考纲 / 错题生成新题").clicked(){self.view="generate".into();}Self::heading(ui,"待确认新题与复习计划");
        for r in self.list("plan"){egui::Frame::group(ui.style()).show(ui,|ui|{ui.label(RichText::new(r.payload["title"].as_str().unwrap_or("学习计划")).strong());if r.payload["type"]=="bankDraft"{ui.small("AI生成草稿，尚未加入正式题库");if ui.button("预览、编辑并确认入库").clicked(){self.editor=serde_json::to_string_pretty(&r.payload["bank"]).unwrap_or_default();self.draft_kind="bank".into();self.view="editor".into();}}else{ui.label(r.payload["text"].as_str().unwrap_or(""));}});}
    }
    fn generate_ui(&mut self,ui:&mut egui::Ui){Self::heading(ui,"生成新题草稿");ui.label(format!("当前勾选{}份资料；可回「资料」选择教材、考纲和往年试题。",self.selected.len()));ui.label("编辑下方出题参数；题型题数合计须等于count。weights为考纲知识点权重。生成后会校验题型、主知识点配比与引用位置。");Self::multiline(ui,&mut self.spec,16);ui.checkbox(&mut self.wrong,"参考最近错题，生成针对性变式");
        if ui.button("生成并预览").clicked(){match serde_json::from_str::<Value>(&self.spec){Ok(mut spec)=>match domain::blueprint(&mut spec){Ok(())=>{let store=self.store.clone();let config=self.config.clone();let selected=self.selected.clone();let wrong=self.wrong;self.job("参考教材、考纲与错题出题…",move||Ok(Output::Bank(ai::generate(&store,&config,spec,&selected,wrong)?)));},Err(e)=>self.status=e.to_string()},Err(e)=>self.status=e.to_string()}}
    }
    fn editor_ui(&mut self,ui:&mut egui::Ui){Self::heading(ui,match self.draft_kind.as_str(){"bank"=>"题库预览与编辑","note"=>"本题笔记","strict"=>"资料严格要求",_=>"编辑题目"});Self::multiline(ui,&mut self.editor,22);if ui.button(if self.draft_kind=="bank"{"校验并确认入库"}else{"保存修改"}).clicked(){let check=(||->Result<()>{if self.draft_kind=="bank"{let bank:Bank=serde_json::from_str(&self.editor)?;bank.validate()?;}else if self.draft_kind=="question"{let q:Question=serde_json::from_str(&self.editor)?;q.validate()?;ensure!(self.edit_id.is_empty()||self.edit_id==q.id,"编辑时不能修改id");}Ok(())})();match check{Ok(())=>self.confirm="save".into(),Err(e)=>self.status=e.to_string()}}
    }
    fn save_editor(&mut self)->Result<()>{match self.draft_kind.as_str(){"bank"=>{let bank:Bank=serde_json::from_str(&self.editor)?;self.bank_import(bank)?;},"question"=>{let q:Question=serde_json::from_str(&self.editor)?;q.validate()?;self.store.save("question",&q.id,serde_json::to_value(&q)?,self.edit_base.as_deref(),false,false)?;},"note"=>{self.store.save("note",&self.edit_id,json!({"id":self.edit_id,"text":self.editor}),self.edit_base.as_deref(),false,false)?;},"strict"=>{let r=self.material.as_ref().ok_or_else(||anyhow::anyhow!("未选择资料"))?;let mut m=r.payload.clone();m["strictRules"]=json!(self.editor);self.store.save("material",&r.entity_id,m,Some(&r.version),false,false)?;},_=>{}}self.view.clear();Ok(())}
    fn settings(&mut self,ui:&mut egui::Ui){Self::heading(ui,"模型与搜索");Self::edit(ui,"视觉评分API Base URL（通常以/v1结尾）",&mut self.config.ai_base,false);Self::edit(ui,"API Key",&mut self.config.ai_key,true);Self::edit(ui,"模型名称（支持图片）",&mut self.config.model,false);Self::edit(ui,"DeepSeek搜索Base URL",&mut self.config.search_base,false);Self::edit(ui,"DeepSeek搜索API Key",&mut self.config.search_key,true);
        Self::heading(ui,"WebDAV同步");Self::edit(ui,"已存在的WebDAV根目录HTTPS地址",&mut self.config.dav_url,false);Self::edit(ui,"用户名",&mut self.config.dav_user,false);Self::edit(ui,"应用专用密码",&mut self.config.dav_password,true);ui.small("在根目录下创建EasyGot/。全部学习记录、教材和图片通过HTTPS传输，云端文件不加密；凭据仅存本机。");
        if ui.button("保存配置到本机Keystore").clicked(){let r=(||->Result<()>{for url in [&self.config.ai_base,&self.config.search_base,&self.config.dav_url]{if !url.is_empty(){crate::network::https(url)?;}}self.bridge.call("saveConfig",&serde_json::to_string(&self.config)?)?;*self.shared.write().map_err(|_|anyhow::anyhow!("配置更新失败"))?=self.config.clone();Ok(())})();self.info(r);}
        if ui.button("立即WebDAV双向同步").clicked(){if let Err(e)=self.save_session(){self.status=e.to_string();}else{let store=self.store.clone();let config=self.config.clone();self.job("同步学习数据，保留冲突版本…",move||Ok(Output::Synced(sync::sync(&store,&config)?)));}}
        if ui.button("测试DeepSeek搜索").clicked(){let config=self.config.clone();self.job("测试搜索接口…",move||{let result=crate::network::search(&config,"学习方法")?;Ok(Output::Info(format!("搜索成功：{}条结果",result.as_array().map_or(0,|v|v.len()))))});}
        Self::heading(ui,"数据与撤销");if ui.button("处理同步冲突").clicked(){self.view="conflicts".into();}if ui.button("历史版本 / 撤销修改").clicked(){self.view="history".into();}
        if ui.button("导出完整JSON备份").clicked(){let store=self.store.clone();self.job("准备完整备份…",move||{let mut value=json!({"backupVersion":1,"revisions":store.revisions(None)?});add_assets(&store,&mut value)?;Ok(Output::Export(value,"EasyGot-backup.json".into()))});}
        if ui.button("导入完整备份（合并版本）").clicked(){let r=self.bridge.call("pick","4").map(|_|());self.info(r);}ui.separator();ui.small("EasyGot 0.1.0-alpha.1 · Rust学习业务 + 原生egui界面 + 完整DSH运行时\nGPL-3.0-only；Harness移动代码MIT，保留上游许可。\nhttps://github.com/weimanmk/EasyGot");
    }
    fn conflicts(&mut self,ui:&mut egui::Ui){Self::heading(ui,"同步冲突");match self.store.conflicts(){Ok(groups)=>{if groups.is_empty(){ui.label("没有待处理冲突");}for group in groups{for r in group{egui::Frame::group(ui.style()).show(ui,|ui|{ui.label(format!("{} · {}",r.kind,r.entity_id));ui.label(domain::clip(&serde_json::to_string_pretty(&r.payload).unwrap_or_default(),4000));if r.deleted{ui.label("此版本为删除标记");}if ui.button("保留此版本，合并双方历史").clicked(){self.editor=r.payload.to_string();self.edit_id=r.entity_id.clone();self.draft_kind=r.kind.clone();self.edit_base=Some(r.version.clone());self.confirm=if r.deleted{"resolve_deleted".into()}else{"resolve".into()};}});}}},Err(e)=>self.status=e.to_string()}}
    fn history(&mut self,ui:&mut egui::Ui){Self::heading(ui,"历史版本与撤销");if let Ok(mut records)=self.store.revisions(None){records.reverse();for r in records.into_iter().take(100){egui::Frame::group(ui.style()).show(ui,|ui|{ui.label(format!("{} · {}",r.kind,domain::clip(&r.entity_id,25)));ui.label(domain::clip(&r.payload.to_string(),300));if ui.button("恢复此版本").clicked(){self.editor=r.payload.to_string();self.edit_id=r.entity_id;self.draft_kind=r.kind;self.confirm=if r.deleted{"restore_deleted".into()}else{"restore".into()};}});}}}
    fn approvals(&mut self,ctx:&egui::Context){if self.confirm.is_empty(){return;}let mut accepted=false;let mut cancelled=false;egui::Window::new("确认操作").collapsible(false).resizable(false).show(ctx,|ui|{ui.label(match self.confirm.as_str(){"ocr"=>"将向你配置的视觉模型发送文档图片或PDF的每一页，可能产生多次API费用。已识别页面会逐页保存，可中断后重试。","save"=>"校验通过后保存内容。同id导入会更新已有题目；修改历史保留，可撤销。","exam"=>"提交整卷，客观题立即评分，主观题保存后联网批改。",_=>"将创建一个新版本，保留历史内容。处理冲突时会把双方版本合并为同一条记录。"});ui.horizontal(|ui|{accepted=ui.button("确认").clicked();cancelled=ui.button("取消").clicked();});});if cancelled{self.confirm.clear();}if !accepted{return;}let action=std::mem::take(&mut self.confirm);match action.as_str(){"save"=>{let r=self.save_editor();self.info(r);},"exam"=>{let r=self.finish_exam();self.info(r);},"ocr"=>self.start_ocr(),_=>{let result=(||->Result<()>{let payload:Value=serde_json::from_str(&self.editor)?;let resolve=action.starts_with("resolve");let deleted=action.ends_with("deleted");self.store.save(&self.draft_kind,&self.edit_id,payload,None,deleted,resolve)?;Ok(())})();self.session=None;self.info(result);}}}
    fn start_ocr(&mut self){let Some(revision)=self.material.clone()else{return;};let store=self.store.clone();let config=self.config.clone();let bridge=self.bridge.clone();self.job("逐页识别资料图片…",move||{let mut m=revision.payload;let mut base=revision.version;if m["format"]=="pdf"&&m["pagesRendered"]!=true{let path=store.asset_path(m["asset"].as_str().unwrap_or(""))?;let pages:Vec<Value>=serde_json::from_str(&bridge.call("renderPdf",path.to_str().unwrap_or(""))?)?;for page in pages{let path=page["path"].as_str().unwrap();let hash=store.asset(&std::fs::read(path)?)?;m["images"].as_array_mut().unwrap().push(json!({"asset":hash,"locator":page["locator"],"recognized":false}));let _=std::fs::remove_file(path);}m["pagesRendered"]=json!(true);base=store.save("material",m["id"].as_str().unwrap(),m.clone(),Some(&base),false,false)?.version;}
        let length=m["images"].as_array().map_or(0,|v|v.len());for i in 0..length{if m["images"][i]["recognized"]==true{continue;}let hash=m["images"][i]["asset"].as_str().unwrap_or("");let text=ai::recognize(&store,&config,hash)?;let locator=m["images"][i]["locator"].clone();m["sections"].as_array_mut().unwrap().push(json!({"locator":locator,"text":text}));m["images"][i]["recognized"]=json!(true);base=store.save("material",m["id"].as_str().unwrap(),m.clone(),Some(&base),false,false)?.version;}Ok(Output::Material(m))});}
}
impl eframe::App for EasyGot{
    fn update(&mut self,ctx:&egui::Context,_frame:&mut eframe::Frame){self.poll();ctx.request_repaint_after(Duration::from_millis(350));egui::TopBottomPanel::top("header").show(ctx,|ui|{ui.add_space(18.);ui.label(RichText::new("E A S Y G O T  /  学有所获").strong().color(Color32::from_rgb(22,116,91)));if self.busy{ui.horizontal(|ui|{ui.spinner();ui.label(&self.status);});}else if !self.status.is_empty(){ui.label(domain::clip(&self.status,200));}if !self.view.is_empty()&&ui.button("返回").clicked(){let _=self.save_session();self.view.clear();}});
        egui::TopBottomPanel::bottom("navigation").show(ctx,|ui|{ui.add_space(5.);ui.horizontal_wrapped(|ui|{for(i,label)in ["学习","题库","资料","助教","设置"].iter().enumerate(){if ui.selectable_label(self.tab==i,*label).clicked(){self.go(i);}}});ui.add_space(18.);});
        egui::CentralPanel::default().show(ctx,|ui|{egui::ScrollArea::vertical().show(ui,|ui|{ui.set_enabled(!self.busy);match self.view.as_str(){"question"=>self.question_ui(ui),"result"=>self.result_ui(ui),"summary"=>self.summary(ui),"material"=>self.material_ui(ui),"editor"=>self.editor_ui(ui),"generate"=>self.generate_ui(ui),"conflicts"=>self.conflicts(ui),"history"=>self.history(ui),_=>match self.tab{0=>self.home(ui),1=>self.bank_ui(ui),2=>self.library(ui),3=>self.assistant(ui),_=>self.settings(ui)}}});});self.approvals(ctx);
    }
    fn on_exit(&mut self,_gl:Option<&eframe::glow::Context>){let _=self.save_session();}
}
fn import_assets(store:&Store,value:&Value)->Result<()>{let mut total=0;if let Some(assets)=value["assets"].as_object(){for(hash,b64)in assets{let bytes=STANDARD.decode(b64.as_str().unwrap_or(""))?;total+=bytes.len();ensure!(total<=60*1024*1024,"备份素材总量超过60MB");ensure!(sha(&bytes)==*hash,"备份素材校验失败");store.asset(&bytes)?;}}Ok(())}
fn add_assets(store:&Store,value:&mut Value)->Result<()>{let mut assets=serde_json::Map::new();let mut total=0;for hash in asset_refs(value){let bytes=std::fs::read(store.asset_path(&hash)?)?;total+=bytes.len();ensure!(total<=60*1024*1024,"JSON备份素材超过60MB，请使用WebDAV");assets.insert(hash,json!(STANDARD.encode(bytes)));}value["assets"]=json!(assets);Ok(())}
